import sys

def tracer(frame, event, arg):
    if event == "line" and frame.f_code.co_name == "lesson":
        print(f"줄 {frame.f_lineno}: {dict(frame.f_locals)}")
    return tracer

def lesson():
    total = 0
    for x in [1, 2, 3]:
        total += x
    return total

sys.settrace(tracer)
lesson()
sys.settrace(None)

import math

def n_params(layers, d, vocab):
    per_layer = 4 * d * d + 8 * d * d    # 어텐션 + MLP(4d)
    return layers * per_layer + vocab * d

for name, L, d in [("small", 12, 768), ("medium", 24, 1024), ("large", 36, 1280)]:
    print(name, f"{n_params(L, d, 50257)/1e6:.0f}M")

for loss in [3.3, 3.0, 2.7]:
    print(f"loss {loss} -> perplexity {math.exp(loss):.1f}")

import hashlib

def shingles(text, n=2):
    w = text.split()
    return {" ".join(w[i:i + n]) for i in range(len(w) - n + 1)}

def h(s, seed):
    return int(hashlib.md5(f"{seed}:{s}".encode()).hexdigest(), 16)

def minhash(sh, k=128):
    return [min(h(s, seed) for s in sh) for seed in range(k)]

a = shingles("the cat sat on the mat")
b = shingles("the cat sat on a mat")
exact = len(a & b) / len(a | b)
sa, sb = minhash(a), minhash(b)
est = sum(x == y for x, y in zip(sa, sb)) / len(sa)
print(f"Jaccard {exact:.2f}, MinHash 추정 {est:.2f}")

class CharTokenizer:
    def encode(self, s): return [ord(c) for c in s]
    def decode(self, ids): return "".join(chr(i) for i in ids)

class ByteTokenizer:
    def encode(self, s): return list(s.encode("utf-8"))
    def decode(self, ids): return bytes(ids).decode("utf-8")

def ratio(s, ids):
    return len(s.encode("utf-8")) / len(ids)

s = "Hello, 🌍! 你好!"
for tok in [CharTokenizer(), ByteTokenizer()]:
    ids = tok.encode(s)
    assert tok.decode(ids) == s            # 왕복 확인
    print(type(tok).__name__, ids[:8], f"압축률 {ratio(s, ids):.2f}")

from collections import Counter
def merge(ids, pair, new):
    out, i = [], 0
    while i < len(ids):
        if i + 1 < len(ids) and (ids[i], ids[i + 1]) == pair:
            out.append(new); i += 2
        else:
            out.append(ids[i]); i += 1
    return out

def train_bpe(text, num_merges):
    ids = list(text.encode("utf-8"))
    merges, vocab = {}, {i: bytes([i]) for i in range(256)}
    for k in range(num_merges):
        pair = Counter(zip(ids, ids[1:])).most_common(1)[0][0]
        merges[pair] = 256 + k
        vocab[256 + k] = vocab[pair[0]] + vocab[pair[1]]
        ids = merge(ids, pair, 256 + k)
    return merges, vocab

def encode(text, merges):
    ids = list(text.encode("utf-8"))
    for pair, new in merges.items():       # 학습 순서대로 (느린 판)
        ids = merge(ids, pair, new)
    return ids

decode = lambda ids, vocab: b"".join(vocab[i] for i in ids).decode("utf-8")
merges, vocab = train_bpe("the cat in the hat", 3)
ids = encode("the quick brown fox", merges)
print(ids, decode(ids, vocab))
